=== FILE: rtl/axil_timer.v ===
`timescale 1ns/1ps
`default_nettype none
// axil_timer: AXI4-Lite timer peripheral with level interrupt.
// Implements microarchitecture_spec.md (prj-ada3a9b9d9:microarchitecture).
// Requirement: req-2b2b91a584. Unreviewed, not yet linted or simulated.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    // ---------------- State (uarch section 2) ----------------
    reg                  aw_held_q;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;
    reg                  bvalid_q;
    reg                  bslverr_q;
    reg                  rvalid_q;
    reg                  rslverr_q;
    reg [31:0]           rdata_q;
    reg                  en_q;
    reg                  ie_q;
    reg                  mode_q;
    reg [31:0]           load_q;
    reg [31:0]           count_q;
    reg                  expired_q;

    // ---------------- Ready signals (uarch section 4, TMR-READY) ----------------
    wire awready = !aw_held_q && !bvalid_q;
    wire wready  = !w_held_q  && !bvalid_q;
    wire arready = !rvalid_q;

    assign s_axil_awready = awready;
    assign s_axil_wready  = wready;
    assign s_axil_arready = arready;

    // ---------------- Write front end (uarch 5.1) ----------------
    wire aw_hs   = s_axil_awvalid && awready;
    wire w_hs    = s_axil_wvalid  && wready;
    wire have_aw = aw_hs || aw_held_q;
    wire have_w  = w_hs  || w_held_q;
    wire wr_fire = have_aw && have_w;

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held_q  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held_q  ? w_strb_q  : s_axil_wstrb;

    // ---------------- Decode (uarch 5.3, TMR-DECODE) ----------------
    wire [ADDR_WIDTH-1:0] wr_hi = wr_addr >> 4;
    wire [ADDR_WIDTH-1:0] rd_hi = s_axil_araddr >> 4;
    wire wr_mapped = (wr_addr[1:0] == 2'b00) && (wr_hi == {ADDR_WIDTH{1'b0}});
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) && (rd_hi == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx = wr_addr[3:2];
    wire [1:0] rd_idx = s_axil_araddr[3:2];

    wire wr_ok      = wr_fire && wr_mapped && (wr_idx != 2'd2);
    wire ctrl_we    = wr_fire && wr_mapped && (wr_idx == 2'd0) && wr_strb[0];
    wire load_sel   = wr_fire && wr_mapped && (wr_idx == 2'd1);
    wire status_clr = wr_fire && wr_mapped && (wr_idx == 2'd3) && wr_strb[0] && wr_data[0];

    // ---------------- Read mux (uarch 6) ----------------
    reg [31:0] rd_val;
    always @(*) begin
        rd_val = 32'h0;
        if (rd_mapped) begin
            case (rd_idx)
                2'd0:    rd_val = {29'b0, mode_q, ie_q, en_q};
                2'd1:    rd_val = load_q;
                2'd2:    rd_val = count_q;
                default: rd_val = {31'b0, expired_q};
            endcase
        end
    end
    wire ar_hs = s_axil_arvalid && arready;

    // ---------------- Timer datapath (uarch 7) ----------------
    wire        cnt_end = en_q && (count_q <= 32'd1);
    wire [31:0] cnt_dec = count_q - 32'd1;

    reg        en_n;
    reg [31:0] count_n;
    always @(*) begin
        en_n    = en_q;
        count_n = count_q;
        if (ctrl_we && wr_data[0]) begin            // row 1
            en_n    = 1'b1;
            count_n = load_q;
        end else if (ctrl_we && cnt_end) begin      // row 2
            en_n    = 1'b0;
            count_n = mode_q ? load_q : 32'd0;
        end else if (ctrl_we && en_q) begin         // row 3
            en_n    = 1'b0;
            count_n = cnt_dec;
        end else if (ctrl_we) begin                 // row 4
            en_n    = 1'b0;
            count_n = count_q;
        end else if (cnt_end && mode_q) begin       // row 5 (old LOAD, D1)
            en_n    = 1'b1;
            count_n = load_q;
        end else if (cnt_end) begin                 // row 6
            en_n    = 1'b0;
            count_n = 32'd0;
        end else if (en_q) begin                    // row 7
            en_n    = 1'b1;
            count_n = cnt_dec;
        end
    end

    reg [31:0] load_n;
    always @(*) begin
        load_n = load_q;
        if (load_sel && wr_strb[0]) load_n[7:0]   = wr_data[7:0];
        if (load_sel && wr_strb[1]) load_n[15:8]  = wr_data[15:8];
        if (load_sel && wr_strb[2]) load_n[23:16] = wr_data[23:16];
        if (load_sel && wr_strb[3]) load_n[31:24] = wr_data[31:24];
    end

    wire expired_n = cnt_end ? 1'b1 : (status_clr ? 1'b0 : expired_q);

    // ---------------- Sequential (synchronous reset, uarch 8) ----------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held_q  <= 1'b0;
            w_data_q  <= 32'h0;
            w_strb_q  <= 4'h0;
            bvalid_q  <= 1'b0;
            bslverr_q <= 1'b0;
            rvalid_q  <= 1'b0;
            rslverr_q <= 1'b0;
            rdata_q   <= 32'h0;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            load_q    <= 32'h0;
            count_q   <= 32'h0;
            expired_q <= 1'b0;
        end else begin
            // hold registers (uarch 5.2)
            aw_held_q <= wr_fire ? 1'b0 : (aw_hs ? 1'b1 : aw_held_q);
            if (aw_hs) aw_addr_q <= s_axil_awaddr;
            w_held_q  <= wr_fire ? 1'b0 : (w_hs ? 1'b1 : w_held_q);
            if (w_hs) begin
                w_data_q <= s_axil_wdata;
                w_strb_q <= s_axil_wstrb;
            end
            // B response (uarch 5.4)
            if (wr_fire) begin
                bvalid_q  <= 1'b1;
                bslverr_q <= !wr_ok;
            end else if (bvalid_q && s_axil_bready) begin
                bvalid_q  <= 1'b0;
            end
            // R response (uarch 6)
            if (ar_hs) begin
                rvalid_q  <= 1'b1;
                rdata_q   <= rd_val;
                rslverr_q <= !rd_mapped;
            end else if (rvalid_q && s_axil_rready) begin
                rvalid_q  <= 1'b0;
            end
            // register file and timer (uarch 7)
            if (ctrl_we) begin
                ie_q   <= wr_data[1];
                mode_q <= wr_data[2];
            end
            en_q      <= en_n;
            count_q   <= count_n;
            load_q    <= load_n;
            expired_q <= expired_n;
        end
    end

    // ---------------- Outputs ----------------
    assign s_axil_bvalid = bvalid_q;
    assign s_axil_bresp  = {bslverr_q, 1'b0};
    assign s_axil_rvalid = rvalid_q;
    assign s_axil_rresp  = {rslverr_q, 1'b0};
    assign s_axil_rdata  = rdata_q;
    assign irq           = expired_q && ie_q;

endmodule
`default_nettype wire
=== END FILE ===
=== FILE: tb/tb_axil_timer.sv ===
`timescale 1ns/1ps
// Self-checking testbench for axil_timer (prj-ada3a9b9d9:rtl-implementation).
module tb_axil_timer;
    localparam integer AW = 4;
    localparam [1:0] OKAY = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg aclk = 1'b0;
    always #5 aclk = ~aclk;
    reg aresetn = 1'b0;

    reg  [AW-1:0] awaddr = 0;
    reg           awvalid = 1'b0;
    wire          awready;
    reg  [31:0]   wdata = 32'h0;
    reg  [3:0]    wstrb = 4'h0;
    reg           wvalid = 1'b0;
    wire          wready;
    wire [1:0]    bresp;
    wire          bvalid;
    reg           bready = 1'b0;
    reg  [AW-1:0] araddr = 0;
    reg           arvalid = 1'b0;
    wire          arready;
    wire [31:0]   rdata;
    wire [1:0]    rresp;
    wire          rvalid;
    reg           rready = 1'b0;
    wire          irq;

    axil_timer #(.ADDR_WIDTH(AW)) dut (
        .aclk(aclk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
        .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
        .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
        .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready),
        .irq(irq)
    );

    integer passed = 0;
    integer failed = 0;
    integer cyc = 0;            // number of rising edges so far
    integer wr_edge = 0;        // edge number that completed the last write
    integer rd_edge = 0;        // edge number that accepted the last read address
    reg     verdict_done = 1'b0;
    reg [8*64-1:0] nonce;

    always @(posedge aclk) cyc <= cyc + 1;

    task check(input cond, input [8*64-1:0] msg);
        begin
            if (cond) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("CHECK FAILED at edge %0d: %0s", cyc, msg);
            end
        end
    endtask

    task verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            end
        end
    endtask

    // AXI4-Lite write. awd / wd: cycles before AW / W is offered.
    task axi_write(input [AW-1:0] addr, input [31:0] data, input [3:0] strb,
                   input integer awd, input integer wd, output [1:0] br);
        integer t;
        reg aw_done, w_done, aw_acc, w_acc;
        reg [1:0] b0;
        begin
            aw_done = 1'b0; w_done = 1'b0; t = 0;
            @(negedge aclk);
            while (!(aw_done && w_done)) begin
                if (!aw_done && t >= awd) begin awvalid = 1'b1; awaddr = addr; end
                if (!w_done && t >= wd) begin wvalid = 1'b1; wdata = data; wstrb = strb; end
                aw_acc = awvalid && awready;
                w_acc  = wvalid && wready;
                if ((aw_acc || aw_done) && (w_acc || w_done)) wr_edge = cyc + 1;
                @(posedge aclk); @(negedge aclk);
                if (aw_acc) begin aw_done = 1'b1; awvalid = 1'b0; end
                if (w_acc)  begin w_done  = 1'b1; wvalid  = 1'b0; end
                if (aw_done && !w_done) check(awready == 1'b0, "awready low while address held");
                if (w_done && !aw_done) check(wready == 1'b0, "wready low while data held");
                if (!(aw_done && w_done)) check(bvalid == 1'b0, "no bvalid before write completes");
                t = t + 1;
            end
            check(bvalid == 1'b1, "bvalid high after completing edge");
            check(!awready && !wready, "AW/W blocked while bvalid high");
            b0 = bresp;
            @(posedge aclk); @(negedge aclk);
            check(bvalid && (bresp == b0), "B held stable while bready low");
            bready = 1'b1;
            @(posedge aclk); @(negedge aclk);
            bready = 1'b0;
            check(bvalid == 1'b0, "bvalid low after bready edge");
            br = b0;
        end
    endtask

    task axi_read(input [AW-1:0] addr, output [31:0] data, output [1:0] rr);
        reg acc;
        reg [31:0] d0;
        reg [1:0] r0;
        begin
            acc = 1'b0;
            @(negedge aclk);
            arvalid = 1'b1; araddr = addr;
            while (!acc) begin
                acc = arready;
                if (acc) rd_edge = cyc + 1;
                @(posedge aclk); @(negedge aclk);
            end
            arvalid = 1'b0;
            check(rvalid == 1'b1, "rvalid high after AR accept edge");
            check(arready == 1'b0, "arready low while rvalid high");
            d0 = rdata; r0 = rresp;
            @(posedge aclk); @(negedge aclk);
            check(rvalid && (rdata == d0) && (rresp == r0), "R held stable while rready low");
            rready = 1'b1;
            @(posedge aclk); @(negedge aclk);
            rready = 1'b0;
            check(rvalid == 1'b0, "rvalid low after rready edge");
            data = d0; rr = r0;
        end
    endtask

    // Wait for irq high; returns the edge number after which irq was first seen high.
    task wait_irq(input integer maxc, output integer at_edge);
        integer i;
        begin
            at_edge = -1;
            for (i = 0; i < maxc && at_edge < 0; i = i + 1) begin
                @(negedge aclk);
                if (irq) at_edge = cyc;
            end
        end
    endtask

    reg [1:0]  resp;
    reg [31:0] rd;
    reg [31:0] rd2;
    integer e0, x1, x2;

    initial begin
        @(negedge aclk); @(negedge aclk); @(negedge aclk);
        aresetn = 1'b1;
        @(negedge aclk);

        // Reset state
        check(awready && wready && arready, "readies high after reset");
        check(!bvalid && !rvalid && !irq, "no responses, irq low after reset");
        axi_read(4'h0, rd, resp); check(rd == 32'h0 && resp == OKAY, "CTRL reset 0");
        axi_read(4'h4, rd, resp); check(rd == 32'h0 && resp == OKAY, "LOAD reset 0");
        axi_read(4'h8, rd, resp); check(rd == 32'h0 && resp == OKAY, "COUNT reset 0");
        axi_read(4'hC, rd, resp); check(rd == 32'h0 && resp == OKAY, "STATUS reset 0");

        // LOAD rw and byte strobes
        axi_write(4'h4, 32'hDEADBEEF, 4'hF, 0, 0, resp); check(resp == OKAY, "LOAD write OKAY");
        axi_read(4'h4, rd, resp); check(rd == 32'hDEADBEEF, "LOAD readback");
        axi_write(4'h4, 32'h11223344, 4'b0101, 0, 0, resp); check(resp == OKAY, "LOAD strobe write OKAY");
        axi_read(4'h4, rd, resp); check(rd == 32'hDE22BE44, "LOAD byte strobes");

        // Ordering: AW before W, W before AW
        axi_write(4'h4, 32'h00000010, 4'hF, 0, 2, resp); check(resp == OKAY, "AW-first write OKAY");
        axi_read(4'h4, rd, resp); check(rd == 32'h10, "AW-first write data");
        axi_write(4'h4, 32'h00000020, 4'hF, 3, 0, resp); check(resp == OKAY, "W-first write OKAY");
        axi_read(4'h4, rd, resp); check(rd == 32'h20, "W-first write data");

        // Error responses
        axi_write(4'h8, 32'h5, 4'hF, 0, 0, resp); check(resp == SLVERR, "COUNT write SLVERR");
        axi_read(4'h8, rd, resp); check(rd == 32'h0 && resp == OKAY, "COUNT unchanged by write");
        axi_write(4'h1, 32'hFFFFFFFF, 4'hF, 0, 0, resp); check(resp == SLVERR, "unmapped write SLVERR");
        axi_read(4'h4, rd, resp); check(rd == 32'h20, "unmapped write does not alias LOAD");
        axi_read(4'h2, rd, resp); check(rd == 32'h0 && resp == SLVERR, "misaligned read SLVERR, rdata 0");
        axi_read(4'h7, rd, resp); check(rd == 32'h0 && resp == SLVERR, "misaligned read 0x7 SLVERR");

        // One-shot, LOAD 20, IE 1
        axi_write(4'h4, 32'd20, 4'hF, 0, 0, resp);
        axi_write(4'h0, 32'h3, 4'h1, 0, 0, resp); e0 = wr_edge;
        check(resp == OKAY, "CTRL start OKAY");
        axi_read(4'h8, rd, resp);
        check(rd == 32'd20 - (rd_edge - 1 - e0), "COUNT trajectory N-k");
        wait_irq(100, x1);
        check(x1 == e0 + 20, "one-shot ends on E+N");
        axi_read(4'h0, rd, resp); check(rd == 32'h2, "one-shot clears EN, keeps IE");
        axi_read(4'h8, rd, resp); check(rd == 32'h0, "one-shot COUNT 0 at end");
        axi_read(4'hC, rd, resp); check(rd == 32'h1, "EXPIRED set");
        axi_write(4'hC, 32'h0, 4'hF, 0, 0, resp); check(irq == 1'b1, "STATUS write 0 clears nothing");
        axi_write(4'hC, 32'h1, 4'h1, 0, 0, resp);
        check(resp == OKAY && irq == 1'b0, "STATUS clear drops irq");
        axi_read(4'hC, rd, resp); check(rd == 32'h0, "EXPIRED cleared");

        // Periodic, LOAD 12, IE 1
        axi_write(4'h4, 32'd12, 4'hF, 0, 0, resp);
        axi_write(4'h0, 32'h7, 4'h1, 0, 0, resp); e0 = wr_edge;
        wait_irq(100, x1);
        check(x1 == e0 + 12, "periodic first end on E+N");
        axi_write(4'hC, 32'h1, 4'h1, 0, 0, resp);
        check(irq == 1'b0, "irq cleared between periods");
        wait_irq(100, x2);
        check(x2 == x1 + 12, "periodic second end on E+2N");
        axi_read(4'h0, rd, resp); check(rd == 32'h7, "periodic keeps EN");
        axi_write(4'h0, 32'h0, 4'h1, 0, 0, resp);
        check(irq == 1'b0, "IE 0 masks irq");
        axi_read(4'h0, rd, resp); check(rd == 32'h0, "stop clears EN");
        axi_read(4'h8, rd, resp);
        axi_read(4'h8, rd2, resp); check(rd == rd2, "COUNT holds after stop");
        axi_write(4'h0, 32'h2, 4'h1, 0, 0, resp);
        check(irq == 1'b1, "IE 1 with EXPIRED set raises irq");
        axi_write(4'hC, 32'h1, 4'h1, 0, 0, resp);
        check(irq == 1'b0, "clear after IE test");

        // CTRL write without wstrb[0] does not disturb a running count
        axi_write(4'h4, 32'd30, 4'hF, 0, 0, resp);
        axi_write(4'h0, 32'h3, 4'h1, 0, 0, resp); e0 = wr_edge;
        axi_write(4'h0, 32'h0, 4'b1110, 0, 0, resp);
        check(resp == OKAY, "CTRL write without wstrb[0] OKAY");
        wait_irq(100, x1);
        check(x1 == e0 + 30, "count undisturbed by strobe-less CTRL write");
        axi_read(4'h0, rd, resp); check(rd == 32'h2, "CTRL after one-shot end");
        axi_write(4'hC, 32'h1, 4'h1, 0, 0, resp);

        // LOAD 0 one-shot, IE 0
        axi_write(4'h4, 32'd0, 4'hF, 0, 0, resp);
        axi_write(4'h0, 32'h1, 4'h1, 0, 0, resp);
        axi_read(4'hC, rd, resp); check(rd == 32'h1, "LOAD 0 one-shot expires");
        axi_read(4'h8, rd, resp); check(rd == 32'h0, "LOAD 0 COUNT 0");
        axi_read(4'h0, rd, resp); check(rd == 32'h0, "LOAD 0 one-shot clears EN");
        check(irq == 1'b0, "irq low with IE 0");

        // Reset during a running periodic count
        axi_write(4'h4, 32'd100, 4'hF, 0, 0, resp);
        axi_write(4'h0, 32'h7, 4'h1, 0, 0, resp);
        @(negedge aclk); aresetn = 1'b0;
        @(negedge aclk); aresetn = 1'b1;
        @(negedge aclk);
        check(awready && wready && arready && !bvalid && !rvalid && !irq, "idle after mid-count reset");
        axi_read(4'h0, rd, resp); check(rd == 32'h0, "CTRL 0 after reset");
        axi_read(4'h4, rd, resp); check(rd == 32'h0, "LOAD 0 after reset");
        axi_read(4'h8, rd, resp); check(rd == 32'h0, "COUNT 0 after reset");
        axi_read(4'hC, rd, resp); check(rd == 32'h0, "STATUS 0 after reset");

        verdict;
        $finish;
    end

    initial begin
        #200000;
        if (!verdict_done) begin
            failed = failed + 1;
            $error("TIMEOUT: testbench did not finish");
            verdict;
            $finish;
        end
    end
endmodule
